declare d jsonb;
begin
  for d in select value from jsonb_array_elements($hh_personality$[{"id":"9721b16c-0101-5a31-8c01-000000000001","key":"hh-socionics-32","version":"v1","instrumentLocale":"en","translationVersion":"hh-original-en-v1","timeframe":"general-self-description","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Socionics — 16-Type Explorer","source":{"title":"Holistic House original reflective questionnaire (unvalidated)","permission":"original-holistic-house","reviewedAt":"2026-10-11","theoreticalBackground":"https://wikisocion.github.io/content/type_names.html","interpretation":"Educational self-reflection only; not an official, validated, or clinical diagnostic instrument. Type candidates are tentative and can be ambiguous."},"answerScale":{"min":1,"max":5},"responseAnchors":["Strongly disagree","Disagree","Neither agree nor disagree","Agree","Strongly agree"],"scoring":{"dimensions":[{"key":"trait.hh_socionics.e","method":"sum","items":["socionics.e.01","socionics.e.02","socionics.e.03","socionics.e.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Extraversion","direction":"non-normative"},{"key":"trait.hh_socionics.i","method":"sum","items":["socionics.i.01","socionics.i.02","socionics.i.03","socionics.i.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Introversion","direction":"non-normative"},{"key":"trait.hh_socionics.n","method":"sum","items":["socionics.n.01","socionics.n.02","socionics.n.03","socionics.n.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Intuition","direction":"non-normative"},{"key":"trait.hh_socionics.s","method":"sum","items":["socionics.s.01","socionics.s.02","socionics.s.03","socionics.s.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Sensing","direction":"non-normative"},{"key":"trait.hh_socionics.l","method":"sum","items":["socionics.l.01","socionics.l.02","socionics.l.03","socionics.l.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Logic","direction":"non-normative"},{"key":"trait.hh_socionics.f","method":"sum","items":["socionics.f.01","socionics.f.02","socionics.f.03","socionics.f.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Ethics / Feeling","direction":"non-normative"},{"key":"trait.hh_socionics.j","method":"sum","items":["socionics.j.01","socionics.j.02","socionics.j.03","socionics.j.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Rationality","direction":"non-normative"},{"key":"trait.hh_socionics.p","method":"sum","items":["socionics.p.01","socionics.p.02","socionics.p.03","socionics.p.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Irrationality / Adaptability","direction":"non-normative"}]},"questions":[{"id":"socionics.e.01","text":"Exchanging ideas with others helps me clarify what I think.","required":true},{"id":"socionics.e.02","text":"Active conversations often give me new momentum.","required":true},{"id":"socionics.e.03","text":"When a group is planning, I tend to join the discussion early.","required":true},{"id":"socionics.e.04","text":"I understand possibilities better while interacting with people.","required":true},{"id":"socionics.i.01","text":"I prefer to develop a thought privately before discussing it.","required":true},{"id":"socionics.i.02","text":"After a busy gathering I usually seek a period of quiet.","required":true},{"id":"socionics.i.03","text":"I often observe a new group before joining its conversation.","required":true},{"id":"socionics.i.04","text":"Solitary reflection helps me recognize my own priorities.","required":true},{"id":"socionics.n.01","text":"I often notice possible future patterns before the concrete details are clear.","required":true},{"id":"socionics.n.02","text":"I enjoy exploring different meanings of the same event.","required":true},{"id":"socionics.n.03","text":"I quickly connect ideas that initially seem unrelated.","required":true},{"id":"socionics.n.04","text":"Imagining how a project could evolve interests me more than listing current facts.","required":true},{"id":"socionics.s.01","text":"I begin solving a problem with what I can observe or test.","required":true},{"id":"socionics.s.02","text":"I notice physical details that affect comfort and practical action.","required":true},{"id":"socionics.s.03","text":"Direct experience is a strong guide when choosing what works.","required":true},{"id":"socionics.s.04","text":"Concrete examples help me understand an idea before abstract explanations.","required":true},{"id":"socionics.l.01","text":"Before accepting an explanation, I check whether its parts fit together logically.","required":true},{"id":"socionics.l.02","text":"I notice inconsistencies between arguments even when people agree emotionally.","required":true},{"id":"socionics.l.03","text":"Clear decision criteria help me evaluate a difficult choice.","required":true},{"id":"socionics.l.04","text":"I often separate the structure of a problem from my feelings about it.","required":true},{"id":"socionics.f.01","text":"I naturally consider how a decision might affect trust between people.","required":true},{"id":"socionics.f.02","text":"I quickly notice changes in a group's emotional atmosphere.","required":true},{"id":"socionics.f.03","text":"Maintaining a human connection matters when I resolve disagreements.","required":true},{"id":"socionics.f.04","text":"I tend to notice the relational meaning behind someone's words.","required":true},{"id":"socionics.j.01","text":"Clear commitments help me move from ideas to action.","required":true},{"id":"socionics.j.02","text":"I prefer to settle priorities before starting several tasks.","required":true},{"id":"socionics.j.03","text":"Concluding a decision can feel more comfortable than leaving everything open.","required":true},{"id":"socionics.j.04","text":"A predictable sequence makes it easier for me to organize a project.","required":true},{"id":"socionics.p.01","text":"I prefer keeping options open while new information is appearing.","required":true},{"id":"socionics.p.02","text":"I find it natural to change course while working on something.","required":true},{"id":"socionics.p.03","text":"Unexpected possibilities often improve my original plan.","required":true},{"id":"socionics.p.04","text":"Exploration usually comes before a firm decision for me.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:739325e95feb1f299566200752b0c65de243f3e4e9fee0a4c767e53e84090aa6"},{"id":"9721b16c-0101-5a31-8c01-000000000002","key":"hh-socionics-32","version":"v1","instrumentLocale":"ru","translationVersion":"hh-original-ru-v1","timeframe":"general-self-description","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Соционика — 16 типов","source":{"title":"Holistic House original reflective questionnaire (unvalidated)","permission":"original-holistic-house","reviewedAt":"2026-10-11","theoreticalBackground":"https://wikisocion.github.io/content/type_names.html","interpretation":"Educational self-reflection only; not an official, validated, or clinical diagnostic instrument. Type candidates are tentative and can be ambiguous."},"answerScale":{"min":1,"max":5},"responseAnchors":["Совсем не согласен","Скорее не согласен","Ни согласен, ни не согласен","Скорее согласен","Полностью согласен"],"scoring":{"dimensions":[{"key":"trait.hh_socionics.e","method":"sum","items":["socionics.e.01","socionics.e.02","socionics.e.03","socionics.e.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Экстраверсия","direction":"non-normative"},{"key":"trait.hh_socionics.i","method":"sum","items":["socionics.i.01","socionics.i.02","socionics.i.03","socionics.i.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Интроверсия","direction":"non-normative"},{"key":"trait.hh_socionics.n","method":"sum","items":["socionics.n.01","socionics.n.02","socionics.n.03","socionics.n.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Интуиция","direction":"non-normative"},{"key":"trait.hh_socionics.s","method":"sum","items":["socionics.s.01","socionics.s.02","socionics.s.03","socionics.s.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Сенсорика","direction":"non-normative"},{"key":"trait.hh_socionics.l","method":"sum","items":["socionics.l.01","socionics.l.02","socionics.l.03","socionics.l.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Логика","direction":"non-normative"},{"key":"trait.hh_socionics.f","method":"sum","items":["socionics.f.01","socionics.f.02","socionics.f.03","socionics.f.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Этика","direction":"non-normative"},{"key":"trait.hh_socionics.j","method":"sum","items":["socionics.j.01","socionics.j.02","socionics.j.03","socionics.j.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Рациональность","direction":"non-normative"},{"key":"trait.hh_socionics.p","method":"sum","items":["socionics.p.01","socionics.p.02","socionics.p.03","socionics.p.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Иррациональность / гибкость","direction":"non-normative"}]},"questions":[{"id":"socionics.e.01","text":"Мне легче понять свою мысль, когда я обсуждаю её с другими.","required":true},{"id":"socionics.e.02","text":"Живые разговоры часто придают мне новый импульс.","required":true},{"id":"socionics.e.03","text":"Когда группа планирует что-то, я обычно рано включаюсь в обсуждение.","required":true},{"id":"socionics.e.04","text":"Я лучше замечаю возможности во взаимодействии с людьми.","required":true},{"id":"socionics.i.01","text":"Мне комфортнее сначала обдумать идею наедине, а потом обсуждать.","required":true},{"id":"socionics.i.02","text":"После многолюдной встречи мне обычно нужна тишина.","required":true},{"id":"socionics.i.03","text":"В новой компании я чаще сначала наблюдаю, а потом включаюсь.","required":true},{"id":"socionics.i.04","text":"Уединённые размышления помогают мне понять собственные приоритеты.","required":true},{"id":"socionics.n.01","text":"Я часто замечаю возможные тенденции будущего раньше, чем проясняются детали.","required":true},{"id":"socionics.n.02","text":"Мне нравится рассматривать разные смыслы одного события.","required":true},{"id":"socionics.n.03","text":"Я быстро связываю идеи, которые сначала кажутся несвязанными.","required":true},{"id":"socionics.n.04","text":"Мне интереснее представлять развитие проекта, чем перечислять текущие факты.","required":true},{"id":"socionics.s.01","text":"Я начинаю решать задачу с того, что можно наблюдать или проверить.","required":true},{"id":"socionics.s.02","text":"Я замечаю телесные и предметные детали, влияющие на комфорт и действия.","required":true},{"id":"socionics.s.03","text":"Личный практический опыт служит мне важным ориентиром.","required":true},{"id":"socionics.s.04","text":"Конкретные примеры помогают мне понять идею раньше абстрактных объяснений.","required":true},{"id":"socionics.l.01","text":"Прежде чем принять объяснение, я проверяю его внутреннюю логику.","required":true},{"id":"socionics.l.02","text":"Я замечаю противоречия в аргументах, даже когда люди эмоционально согласны.","required":true},{"id":"socionics.l.03","text":"Чёткие критерии помогают мне оценивать трудный выбор.","required":true},{"id":"socionics.l.04","text":"Я часто отделяю устройство проблемы от чувств, которые она вызывает.","required":true},{"id":"socionics.f.01","text":"Мне естественно учитывать, как решение повлияет на доверие между людьми.","required":true},{"id":"socionics.f.02","text":"Я быстро замечаю перемены эмоциональной атмосферы в группе.","required":true},{"id":"socionics.f.03","text":"При разрешении разногласий мне важно сохранять человеческую связь.","required":true},{"id":"socionics.f.04","text":"Я часто замечаю смысл отношений, который стоит за словами собеседника.","required":true},{"id":"socionics.j.01","text":"Чёткие договорённости помогают мне переходить от идей к действиям.","required":true},{"id":"socionics.j.02","text":"Мне удобнее заранее определить приоритеты перед несколькими делами.","required":true},{"id":"socionics.j.03","text":"Завершённое решение обычно комфортнее для меня, чем множество открытых вариантов.","required":true},{"id":"socionics.j.04","text":"Предсказуемая последовательность помогает мне организовывать проект.","required":true},{"id":"socionics.p.01","text":"Я предпочитаю оставлять варианты открытыми, пока появляется новая информация.","required":true},{"id":"socionics.p.02","text":"Мне естественно менять маршрут уже в процессе работы.","required":true},{"id":"socionics.p.03","text":"Неожиданные возможности часто улучшают мой первоначальный план.","required":true},{"id":"socionics.p.04","text":"Для меня исследование вариантов обычно предшествует твёрдому решению.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:c4f7087981e8e4326b978bba6237de8db910679044e2a9e3e343a80f5d56fc4d"},{"id":"9721b16c-0201-5a31-8c01-000000000003","key":"hh-enneagram-36","version":"v1","instrumentLocale":"en","translationVersion":"hh-original-en-v1","timeframe":"general-self-description","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Enneagram — Nine Motivations","source":{"title":"Holistic House original reflective questionnaire (unvalidated)","permission":"original-holistic-house","reviewedAt":"2026-10-11","theoreticalBackground":"https://pubmed.ncbi.nlm.nih.gov/33332604/","interpretation":"Educational self-reflection only; not an official, validated, or clinical diagnostic instrument. Type candidates are tentative and can be ambiguous."},"answerScale":{"min":1,"max":5},"responseAnchors":["Strongly disagree","Disagree","Neither agree nor disagree","Agree","Strongly agree"],"scoring":{"dimensions":[{"key":"trait.hh_enneagram.one","method":"sum","items":["enneagram.one.01","enneagram.one.02","enneagram.one.03","enneagram.one.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Integrity / Improvement","direction":"non-normative"},{"key":"trait.hh_enneagram.two","method":"sum","items":["enneagram.two.01","enneagram.two.02","enneagram.two.03","enneagram.two.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Care / Being Useful","direction":"non-normative"},{"key":"trait.hh_enneagram.three","method":"sum","items":["enneagram.three.01","enneagram.three.02","enneagram.three.03","enneagram.three.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Achievement / Impact","direction":"non-normative"},{"key":"trait.hh_enneagram.four","method":"sum","items":["enneagram.four.01","enneagram.four.02","enneagram.four.03","enneagram.four.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Identity / Authenticity","direction":"non-normative"},{"key":"trait.hh_enneagram.five","method":"sum","items":["enneagram.five.01","enneagram.five.02","enneagram.five.03","enneagram.five.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Understanding / Independence","direction":"non-normative"},{"key":"trait.hh_enneagram.six","method":"sum","items":["enneagram.six.01","enneagram.six.02","enneagram.six.03","enneagram.six.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Security / Loyalty","direction":"non-normative"},{"key":"trait.hh_enneagram.seven","method":"sum","items":["enneagram.seven.01","enneagram.seven.02","enneagram.seven.03","enneagram.seven.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Possibilities / Exploration","direction":"non-normative"},{"key":"trait.hh_enneagram.eight","method":"sum","items":["enneagram.eight.01","enneagram.eight.02","enneagram.eight.03","enneagram.eight.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Autonomy / Protection","direction":"non-normative"},{"key":"trait.hh_enneagram.nine","method":"sum","items":["enneagram.nine.01","enneagram.nine.02","enneagram.nine.03","enneagram.nine.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Harmony / Stability","direction":"non-normative"}]},"questions":[{"id":"enneagram.one.01","text":"It matters to me to act in line with my principles even when nobody watches.","required":true},{"id":"enneagram.one.02","text":"I notice where a process could become more accurate or fair.","required":true},{"id":"enneagram.one.03","text":"Doing a task responsibly often brings me peace of mind.","required":true},{"id":"enneagram.one.04","text":"I feel motivated to correct a problem when I know a better approach.","required":true},{"id":"enneagram.two.01","text":"Being available to people I care about gives my days meaning.","required":true},{"id":"enneagram.two.02","text":"I often sense needs that people have not yet said aloud.","required":true},{"id":"enneagram.two.03","text":"I feel appreciated when my help genuinely makes someone's life easier.","required":true},{"id":"enneagram.two.04","text":"Strong relationships matter as much to me as individual achievements.","required":true},{"id":"enneagram.three.01","text":"A visible result encourages me to continue working toward a goal.","required":true},{"id":"enneagram.three.02","text":"I naturally notice what would make an effort more effective.","required":true},{"id":"enneagram.three.03","text":"Being recognized for useful accomplishments can motivate me.","required":true},{"id":"enneagram.three.04","text":"When circumstances change, I can adapt how I present my strengths.","required":true},{"id":"enneagram.four.01","text":"Expressing what feels uniquely true to me is important.","required":true},{"id":"enneagram.four.02","text":"I pay close attention to subtle emotional shades in an experience.","required":true},{"id":"enneagram.four.03","text":"I value being understood as an individual rather than fitting a standard role.","required":true},{"id":"enneagram.four.04","text":"Creative expression helps me make sense of difficult feelings.","required":true},{"id":"enneagram.five.01","text":"I feel more secure when I understand how something works.","required":true},{"id":"enneagram.five.02","text":"I enjoy investigating a subject deeply before taking a public position.","required":true},{"id":"enneagram.five.03","text":"Protecting time for quiet thinking is especially valuable to me.","required":true},{"id":"enneagram.five.04","text":"A clear explanation can be more satisfying to me than quick agreement.","required":true},{"id":"enneagram.six.01","text":"I tend to consider risks before committing to a new plan.","required":true},{"id":"enneagram.six.02","text":"Trust grows for me through consistent actions rather than promises alone.","required":true},{"id":"enneagram.six.03","text":"I value people who remain dependable during uncertainty.","required":true},{"id":"enneagram.six.04","text":"Preparing alternatives helps me stay steady in change.","required":true},{"id":"enneagram.seven.01","text":"Exploring new possibilities gives me a sense of vitality.","required":true},{"id":"enneagram.seven.02","text":"I can quickly notice an interesting opportunity in an unexpected change.","required":true},{"id":"enneagram.seven.03","text":"Variety often helps me stay engaged with a project.","required":true},{"id":"enneagram.seven.04","text":"I enjoy turning an ordinary plan into an interesting experience.","required":true},{"id":"enneagram.eight.01","text":"It matters to me to be able to speak directly when something is unfair.","required":true},{"id":"enneagram.eight.02","text":"I readily take initiative when a situation calls for decisive action.","required":true},{"id":"enneagram.eight.03","text":"Protecting people or values I care about strongly motivates me.","required":true},{"id":"enneagram.eight.04","text":"I prefer clear, straightforward conversations about difficult issues.","required":true},{"id":"enneagram.nine.01","text":"I usually notice what different sides of a disagreement have in common.","required":true},{"id":"enneagram.nine.02","text":"A calm and steady environment helps me think clearly.","required":true},{"id":"enneagram.nine.03","text":"I value solutions that leave room for several people's needs.","required":true},{"id":"enneagram.nine.04","text":"I often help others feel more comfortable without taking center stage.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:1714cac50b4078864bc98ffbdcd3b35f27ae1454abb3a60579213263e226d566"},{"id":"9721b16c-0201-5a31-8c01-000000000004","key":"hh-enneagram-36","version":"v1","instrumentLocale":"ru","translationVersion":"hh-original-ru-v1","timeframe":"general-self-description","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Эннеаграмма — 9 мотиваций","source":{"title":"Holistic House original reflective questionnaire (unvalidated)","permission":"original-holistic-house","reviewedAt":"2026-10-11","theoreticalBackground":"https://pubmed.ncbi.nlm.nih.gov/33332604/","interpretation":"Educational self-reflection only; not an official, validated, or clinical diagnostic instrument. Type candidates are tentative and can be ambiguous."},"answerScale":{"min":1,"max":5},"responseAnchors":["Совсем не согласен","Скорее не согласен","Ни согласен, ни не согласен","Скорее согласен","Полностью согласен"],"scoring":{"dimensions":[{"key":"trait.hh_enneagram.one","method":"sum","items":["enneagram.one.01","enneagram.one.02","enneagram.one.03","enneagram.one.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Принципиальность / совершенствование","direction":"non-normative"},{"key":"trait.hh_enneagram.two","method":"sum","items":["enneagram.two.01","enneagram.two.02","enneagram.two.03","enneagram.two.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Забота / нужность","direction":"non-normative"},{"key":"trait.hh_enneagram.three","method":"sum","items":["enneagram.three.01","enneagram.three.02","enneagram.three.03","enneagram.three.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Достижение / результат","direction":"non-normative"},{"key":"trait.hh_enneagram.four","method":"sum","items":["enneagram.four.01","enneagram.four.02","enneagram.four.03","enneagram.four.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Самобытность / подлинность","direction":"non-normative"},{"key":"trait.hh_enneagram.five","method":"sum","items":["enneagram.five.01","enneagram.five.02","enneagram.five.03","enneagram.five.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Понимание / автономия","direction":"non-normative"},{"key":"trait.hh_enneagram.six","method":"sum","items":["enneagram.six.01","enneagram.six.02","enneagram.six.03","enneagram.six.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Надёжность / лояльность","direction":"non-normative"},{"key":"trait.hh_enneagram.seven","method":"sum","items":["enneagram.seven.01","enneagram.seven.02","enneagram.seven.03","enneagram.seven.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Возможности / исследование","direction":"non-normative"},{"key":"trait.hh_enneagram.eight","method":"sum","items":["enneagram.eight.01","enneagram.eight.02","enneagram.eight.03","enneagram.eight.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Самостоятельность / защита","direction":"non-normative"},{"key":"trait.hh_enneagram.nine","method":"sum","items":["enneagram.nine.01","enneagram.nine.02","enneagram.nine.03","enneagram.nine.04"],"min":4,"max":20,"dimensionClass":"trait","sourceConstruct":"Гармония / устойчивость","direction":"non-normative"}]},"questions":[{"id":"enneagram.one.01","text":"Для меня важно следовать принципам, даже если никто не наблюдает.","required":true},{"id":"enneagram.one.02","text":"Я замечаю, где процессы можно сделать точнее или справедливее.","required":true},{"id":"enneagram.one.03","text":"Ответственное выполнение задачи приносит мне спокойствие.","required":true},{"id":"enneagram.one.04","text":"Мне хочется исправить недостаток, когда я знаю лучший способ.","required":true},{"id":"enneagram.two.01","text":"Возможность поддерживать близких придаёт моим дням смысл.","required":true},{"id":"enneagram.two.02","text":"Я часто чувствую потребности людей ещё до того, как они их озвучат.","required":true},{"id":"enneagram.two.03","text":"Я чувствую признательность, когда моя помощь действительно облегчает чью-то жизнь.","required":true},{"id":"enneagram.two.04","text":"Близкие отношения для меня не менее важны, чем личные достижения.","required":true},{"id":"enneagram.three.01","text":"Видимый результат вдохновляет меня дальше двигаться к цели.","required":true},{"id":"enneagram.three.02","text":"Я легко замечаю, как сделать усилия более результативными.","required":true},{"id":"enneagram.three.03","text":"Признание полезных достижений может сильно меня мотивировать.","required":true},{"id":"enneagram.three.04","text":"Когда обстоятельства меняются, я умею иначе представить свои сильные стороны.","required":true},{"id":"enneagram.four.01","text":"Мне важно выражать то, что ощущается для меня по-настоящему своим.","required":true},{"id":"enneagram.four.02","text":"Я тонко различаю оттенки переживаний.","required":true},{"id":"enneagram.four.03","text":"Мне важно, чтобы меня понимали как личность, а не как стандартную роль.","required":true},{"id":"enneagram.four.04","text":"Творческое выражение помогает мне осмыслять трудные чувства.","required":true},{"id":"enneagram.five.01","text":"Я чувствую больше опоры, когда понимаю устройство происходящего.","required":true},{"id":"enneagram.five.02","text":"Мне нравится глубоко исследовать тему, прежде чем высказывать позицию.","required":true},{"id":"enneagram.five.03","text":"Для меня особенно ценно беречь время для спокойных размышлений.","required":true},{"id":"enneagram.five.04","text":"Понятное объяснение может быть для меня важнее быстрого согласия.","required":true},{"id":"enneagram.six.01","text":"Перед новым планом я склонен учитывать возможные риски.","required":true},{"id":"enneagram.six.02","text":"Доверие у меня растёт благодаря последовательным поступкам, а не только обещаниям.","required":true},{"id":"enneagram.six.03","text":"Я ценю людей, которые остаются надёжными в неопределённости.","required":true},{"id":"enneagram.six.04","text":"Подготовка запасных вариантов помогает мне сохранять устойчивость при переменах.","required":true},{"id":"enneagram.seven.01","text":"Исследование новых возможностей наполняет меня энергией.","required":true},{"id":"enneagram.seven.02","text":"Я быстро замечаю интересную возможность в неожиданной перемене.","required":true},{"id":"enneagram.seven.03","text":"Разнообразие помогает мне сохранять интерес к проекту.","required":true},{"id":"enneagram.seven.04","text":"Мне нравится превращать обычный план в интересный опыт.","required":true},{"id":"enneagram.eight.01","text":"Мне важно иметь возможность прямо высказаться, когда что-то несправедливо.","required":true},{"id":"enneagram.eight.02","text":"Я охотно проявляю инициативу, если ситуация требует решительных действий.","required":true},{"id":"enneagram.eight.03","text":"Защита дорогих мне людей и ценностей сильно меня мотивирует.","required":true},{"id":"enneagram.eight.04","text":"В трудных вопросах я предпочитаю ясный и прямой разговор.","required":true},{"id":"enneagram.nine.01","text":"При разногласии я часто замечаю, что объединяет разные стороны.","required":true},{"id":"enneagram.nine.02","text":"Спокойная, стабильная атмосфера помогает мне мыслить яснее.","required":true},{"id":"enneagram.nine.03","text":"Я ценю решения, которые учитывают потребности нескольких людей.","required":true},{"id":"enneagram.nine.04","text":"Я часто помогаю другим чувствовать себя спокойнее, не оказываясь в центре внимания.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:8cbeab16f4bda2b93a26d078d4ea98fe16f1ade9ee3ff3ed45379360a24a0492"},{"id":"9721b16c-0301-5a31-8c01-000000000005","key":"hh-disc-style-20","version":"v1","instrumentLocale":"en","translationVersion":"hh-original-en-v1","timeframe":"general-self-description","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Behavioral Styles — D/I/S/C","source":{"title":"Holistic House original reflective questionnaire (unvalidated)","permission":"original-holistic-house","reviewedAt":"2026-10-11","theoreticalBackground":"Holistic House original educational framework","interpretation":"Educational self-reflection only; not an official, validated, or clinical diagnostic instrument. Type candidates are tentative and can be ambiguous."},"answerScale":{"min":1,"max":5},"responseAnchors":["Strongly disagree","Disagree","Neither agree nor disagree","Agree","Strongly agree"],"scoring":{"dimensions":[{"key":"trait.hh_disc.d","method":"sum","items":["disc.d.01","disc.d.02","disc.d.03","disc.d.04","disc.d.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Direct Action","direction":"non-normative"},{"key":"trait.hh_disc.i","method":"sum","items":["disc.i.01","disc.i.02","disc.i.03","disc.i.04","disc.i.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Social Influence","direction":"non-normative"},{"key":"trait.hh_disc.s","method":"sum","items":["disc.s.01","disc.s.02","disc.s.03","disc.s.04","disc.s.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Steady Support","direction":"non-normative"},{"key":"trait.hh_disc.c","method":"sum","items":["disc.c.01","disc.c.02","disc.c.03","disc.c.04","disc.c.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Careful Analysis","direction":"non-normative"}]},"questions":[{"id":"disc.d.01","text":"When priorities are unclear, I often suggest a concrete decision.","required":true},{"id":"disc.d.02","text":"I am comfortable naming a problem directly and proposing action.","required":true},{"id":"disc.d.03","text":"I tend to focus conversations on what can be changed next.","required":true},{"id":"disc.d.04","text":"Taking responsibility during a challenge feels natural to me.","required":true},{"id":"disc.d.05","text":"I appreciate colleagues who are clear and decisive.","required":true},{"id":"disc.i.01","text":"Sharing enthusiasm often helps me bring people together.","required":true},{"id":"disc.i.02","text":"I naturally notice how to make a group discussion more lively.","required":true},{"id":"disc.i.03","text":"New contacts and conversations can energize my work.","required":true},{"id":"disc.i.04","text":"I am comfortable encouraging people toward a shared idea.","required":true},{"id":"disc.i.05","text":"I like finding an inviting way to present a proposal.","required":true},{"id":"disc.s.01","text":"People can usually rely on me to follow through at a steady pace.","required":true},{"id":"disc.s.02","text":"I notice when a teammate could use patient support.","required":true},{"id":"disc.s.03","text":"I prefer thoughtful transitions to sudden unnecessary change.","required":true},{"id":"disc.s.04","text":"Listening carefully is one of my useful skills in a team.","required":true},{"id":"disc.s.05","text":"I often help maintain stability during a busy period.","required":true},{"id":"disc.c.01","text":"I like checking evidence before making an important recommendation.","required":true},{"id":"disc.c.02","text":"Clear standards help me produce work I trust.","required":true},{"id":"disc.c.03","text":"I notice details that could affect the reliability of a result.","required":true},{"id":"disc.c.04","text":"I often ask what assumptions underlie a conclusion.","required":true},{"id":"disc.c.05","text":"A carefully structured approach helps me solve complex tasks.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:d20ee32781a21001b350c244f578041480b6b249665f495443cfb82ec983ec08"},{"id":"9721b16c-0301-5a31-8c01-000000000006","key":"hh-disc-style-20","version":"v1","instrumentLocale":"ru","translationVersion":"hh-original-ru-v1","timeframe":"general-self-description","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Поведенческие стили — D/I/S/C","source":{"title":"Holistic House original reflective questionnaire (unvalidated)","permission":"original-holistic-house","reviewedAt":"2026-10-11","theoreticalBackground":"Holistic House original educational framework","interpretation":"Educational self-reflection only; not an official, validated, or clinical diagnostic instrument. Type candidates are tentative and can be ambiguous."},"answerScale":{"min":1,"max":5},"responseAnchors":["Совсем не согласен","Скорее не согласен","Ни согласен, ни не согласен","Скорее согласен","Полностью согласен"],"scoring":{"dimensions":[{"key":"trait.hh_disc.d","method":"sum","items":["disc.d.01","disc.d.02","disc.d.03","disc.d.04","disc.d.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Прямое действие","direction":"non-normative"},{"key":"trait.hh_disc.i","method":"sum","items":["disc.i.01","disc.i.02","disc.i.03","disc.i.04","disc.i.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Вовлечение людей","direction":"non-normative"},{"key":"trait.hh_disc.s","method":"sum","items":["disc.s.01","disc.s.02","disc.s.03","disc.s.04","disc.s.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Стабильная поддержка","direction":"non-normative"},{"key":"trait.hh_disc.c","method":"sum","items":["disc.c.01","disc.c.02","disc.c.03","disc.c.04","disc.c.05"],"min":5,"max":25,"dimensionClass":"trait","sourceConstruct":"Точность и анализ","direction":"non-normative"}]},"questions":[{"id":"disc.d.01","text":"Когда приоритеты неясны, я часто предлагаю конкретное решение.","required":true},{"id":"disc.d.02","text":"Мне удобно прямо назвать проблему и предложить действие.","required":true},{"id":"disc.d.03","text":"В обсуждениях я обычно сосредотачиваюсь на том, что можно изменить дальше.","required":true},{"id":"disc.d.04","text":"Мне естественно брать ответственность в сложной ситуации.","required":true},{"id":"disc.d.05","text":"Я ценю в коллегах ясность и решительность.","required":true},{"id":"disc.i.01","text":"Когда я делюсь энтузиазмом, это часто объединяет людей.","required":true},{"id":"disc.i.02","text":"Я легко замечаю, как оживить групповое обсуждение.","required":true},{"id":"disc.i.03","text":"Новые знакомства и разговоры могут придавать мне энергию.","required":true},{"id":"disc.i.04","text":"Мне комфортно вдохновлять людей на общую идею.","required":true},{"id":"disc.i.05","text":"Мне нравится находить привлекательную форму представления идеи.","required":true},{"id":"disc.s.01","text":"Люди обычно могут рассчитывать на мой размеренный и последовательный подход.","required":true},{"id":"disc.s.02","text":"Я замечаю, когда коллеге нужна спокойная поддержка.","required":true},{"id":"disc.s.03","text":"Я предпочитаю продуманные изменения резким и ненужным переменам.","required":true},{"id":"disc.s.04","text":"Внимательное слушание — одно из моих полезных качеств в команде.","required":true},{"id":"disc.s.05","text":"В напряжённые периоды я часто помогаю сохранять стабильность.","required":true},{"id":"disc.c.01","text":"Мне нравится проверять основания перед важной рекомендацией.","required":true},{"id":"disc.c.02","text":"Чёткие стандарты помогают мне доверять качеству своей работы.","required":true},{"id":"disc.c.03","text":"Я замечаю детали, от которых зависит надёжность результата.","required":true},{"id":"disc.c.04","text":"Я часто уточняю, на каких предположениях основан вывод.","required":true},{"id":"disc.c.05","text":"Продуманная структура помогает мне решать сложные задачи.","required":true}],"optionalContext":[],"suggestedRepeatDays":null,"contentHash":"sha256:88e22bbdb759d4c144879fb886d9b8ed36898a85a4cd48e0ea41f5abf51569d7"},{"id":"9721b16c-0401-5a31-8c01-000000000007","key":"hh-temperamen